"""Decoder for the Unix compress (.Z) LZW stream format."""

class InvalidCompress(ValueError):
    pass


def decompress(data: bytes) -> bytes:
    if len(data) < 3 or data[:2] != b"\x1f\x9d":
        raise InvalidCompress("invalid compress header")
    flags = data[2]
    maxbits = flags & 0x1f
    block = bool(flags & 0x80)
    if flags & 0x60 or maxbits < 9 or maxbits > 16:
        raise InvalidCompress("invalid compress flags")
    src = data[3:]
    out = bytearray()
    width = 9
    limit = 1 << width
    maxcode = (1 << maxbits) - 1
    clear = 256 if block else -1
    nextcode = 257 if block else 256
    table = [bytes([i]) for i in range(256)] + [None] * ((1 << maxbits) - 256)
    bitpos = 0
    old = None

    def code_at(pos, bits):
        # Compress packs codes least-significant bit first into width-sized
        # groups.  Width changes begin at a group boundary.
        group = (pos // (bits * 8)) * bits
        off = pos - group * 8
        if group + bits > len(src):
            return None
        val = int.from_bytes(src[group:group + bits], "little")
        return (val >> off) & ((1 << bits) - 1)

    while True:
        code = code_at(bitpos, width)
        if code is None:
            break
        bitpos += width
        if code == clear:
            width = 9
            limit = 1 << width
            nextcode = 257
            old = None
            continue
        if code > nextcode or code >= len(table):
            raise InvalidCompress("invalid LZW code")
        if old is None:
            if code >= 256 or table[code] is None:
                raise InvalidCompress("invalid initial code")
            entry = table[code]
            out.extend(entry)
            old = entry
            continue
        if code < nextcode and table[code] is not None:
            entry = table[code]
        elif code == nextcode:
            entry = old + old[:1]
        else:
            raise InvalidCompress("invalid LZW code")
        out.extend(entry)
        if nextcode <= maxcode:
            table[nextcode] = old + entry[:1]
            nextcode += 1
            if nextcode >= limit and width < maxbits:
                width += 1
                limit = 1 << width
        old = entry
    if not out:
        raise InvalidCompress("empty compress stream")
    return bytes(out)
